<script>
(function(){
  var $=function(i){return document.getElementById(i)},P=Math.PI;
  function L(a,b,q){return a+(b-a)*q}
  function T(id,v){$(id).setAttribute('transform',v)}
  var S=['scene-closeup','scene-tumble','scene-behind','scene-skyup','scene-dive'].map($);
  var M=[['character-small-1',65,268,70,240,0.8,1.05,20,0.03],
         ['character-small-2',140,258,148,235,0.6,0.8,-30,-0.04],
         ['character-small-3',270,170,282,140,0.6,0.7,60,0.05],
         ['character-small-4',140,190,150,150,0.45,0.6,10,0.03],
         ['character-small-5',165,152,172,120,0.2,0.3,-20,0.02]];
  function render(t){
    t=((+t%5000)+5000)%5000;
    var i=t<350?0:t<1050?1:t<1750?2:t<3200?3:4,k,d,q,s;
    for(k=0;k<5;k++)S[k].setAttribute('display',k===i?'inline':'none');
    if(i===0){
      var b=Math.sin(t*P/120);s=1+t*0.0002;
      T('character-yellow','translate(150 '+(150-t*0.01)+') scale('+s+') translate(-150 -150)');
      T('head','translate(0 '+(2.5*b)+')');
      T('belly','translate(0 '+(-1.5*b)+')');
      T('hand-left','translate(0 '+(-1.5*b)+')');
      T('hand-right','translate(0 '+(-1.5*b)+')');
    }else if(i===1){
      d=t-700;
      T('tumble-bg','translate(0 '+(d*0.03)+')');
      T('character-yellow-tumble','translate('+(-d*0.03)+' '+(d*0.02)+') rotate('+(d*0.035)+' 190 180)');
    }else if(i===2){
      d=t-1400;s=1+d*0.0003;
      T('behind-bg','rotate('+(d*0.015)+' 150 150) translate('+(d*0.03)+' '+(-d*0.03)+')');
      T('character-yellow-behind','translate(170 190) rotate('+(d*0.02)+') scale('+s+') translate(-170 -190)');
    }else if(i===3){
      q=(t-2100)/750;s=Math.pow(0.34,1-q);
      T('sky-clouds','translate(150 150) scale('+(1+0.5*q)+') translate(-150 '+(-150-20*q)+')');
      $('sky-haze').setAttribute('opacity',Math.max(0,Math.min(1,q))*0.8);
      T('sky-mountain','translate('+((1-q)*60)+' '+((1-q)*90)+')');
      T('character-yellow-below','translate('+L(135,145,q)+' '+L(42,85,q)+') scale('+s+') translate(-145 -85)');
      for(k=0;k<M.length;k++){var m=M[k];
        T(m[0],'translate('+L(m[1],m[3],q)+' '+L(m[2],m[4],q)+') rotate('+(m[7]+m[8]*t)+') scale('+L(m[5],m[6],q)+')');}
    }else{
      var p=(t-3550)/700,cx,cy,sx,sy,r=0,wob=0;
      T('landscape','translate(0 '+(-130*p)+')');
      if(p<1){var pp=Math.max(p,-0.3);sx=Math.pow(2.8,1-pp);sy=Math.pow(4.5,1-pp);cx=L(89,165,pp);cy=L(93,205,pp);}
      else{var w=p-1;sx=sy=L(1,0.66,w);cx=L(165,143,w);cy=L(205,183,w);r=-15*w;wob=0.06*Math.sin((t-4250)*P/175);}
      T('character-yellow-falling','translate('+cx+' '+cy+') rotate('+r+') scale('+sx+' '+sy+')');
      T('falling-mouth','scale(1 '+(1+wob)+')');
      var ax,ay;
      if(p<1){ax=L(292,178,p);ay=L(95,90,p);}else{ax=L(178,200,p-1);ay=L(90,110,p-1);}
      T('character-small-a','translate('+ax+' '+ay+') rotate('+(15+0.03*t)+')');
      T('character-small-b','translate('+(62+23*p)+' '+(10+40*p)+') rotate('+(-20-0.025*t)+')');
      T('character-small-c','translate('+(141+27*p)+' '+(-38+43*p)+') rotate('+(40+0.02*t)+')');
    }
  }
  window.nwb={render:render};
  render(0);
})();
</script>
